DataColumn.guide:
/**
 * DTS declaration: DataColumn = {
    /** 列名称 */
    name: string;
    /**
     * 列值类型。已知类型见 `ColumnType`；未知业务类型按 unknown 处理。
     *
     * 常用值：`'string'` | `'number'` | `'boolean'` | `'date'` | `'datetime'`
     */
    type: ColumnType;
    /** 列标题（UI 表头 / 表单标签 / 描述列标题）。未设置时 UI 回退到 `name` */
    label?: string;
    /** 是否允许数据库 NULL 值 */
    allowDBNull?: boolean;
    /** 默认值 */
    defaultValue?: unknown;
    /** 是否为主键字段 */
    isPrimaryKey?: boolean;
    /** 是否自增 */
    autoIncrement?: boolean;
    /**
     * 正式模型字段是否允许作为通用 AI 批量新增的生成目标列。
     * 该标志属于 DataTable.columns 字段元数据，不是业务行或 DataView 配置；未设置时按未启用处理。
     * 此标志不授予数据权限，仍须消费原新增权限与字段权限。
     */
    allowAIAdd?: boolean;
    /**
     * 是否为框架计算列（如 `_pk`）。
     *
     * 计算列的值由框架自动维护，不参与序列化（`DataTable.toJson()` 自动排除）。
     * UI 组件可通过 `columns.filter(c => !c.isComputed)` 获取用户定义列。
     */
    isComputed?: boolean;
    /**
     * UI 必填标记。
     *
     * - `true`：表单中必填（生成 required 验证规则）
     * - 未设置时回退到 `!allowDBNull`（allowDBNull 显式为 false 也视为必填）
     */
    required?: boolean;
    /** 字符串最小长度（仅 type 为 string 系列时生效） */
    minLength?: number;
    /** 字符串最大长度（仅 type 为 string 系列时生效） */
    maxLength?: number;
    /** 数值最小值（仅 type 为 number 系列时生效） */
    min?: number;
    /** 数值最大值（仅 type 为 number 系列时生效） */
    max?: number;
    /**
     * 正则校验模式（字符串形式，运行时编译为 RegExp）。
     *
     * @example `"^[\\w.-]+@[\\w.-]+\\.\\w+$"`
     */
    pattern?: string;
    /** 正则校验失败时的自定义提示消息。未设置时使用默认提示 */
    patternMessage?: string;
    /** 字符串首尾空白：reject 保存时拒绝，normalize 保存前去除；两者都把纯空白视为空值。 */
    trim?: 'reject' | 'normalize';
    /** 保存后本视图保留行中的非空值不得重复；只核已加载及待提交行，不替代服务端约束。 */
    unique?: boolean;
    /** 仅本视图待新增行可写；既有行字段只读，保存拒绝对其修改。 */
    immutable?: boolean;
    /** 保存前核对非空值在选项视图中唯一存在；fill 在本字段新增或变更时把匹配选项写回本行。 */
    optionsView?: DataColumnOptionsView;
    /** 值函数字段，保存前按 DataViewFilter 值函数合同校验。 */
    valueFunction?: DataColumnValueFunction;
    /**
     * 计算列表达式（JS 表达式字符串）。
     *
     * 行字段直接引用（无需前缀），外部上下文通过 `ctx` 对象引用，
     * 子表聚合通过 `$sum` / `$count` / `$avg` / `$min` / `$max` / `$list` / `$join` 函数。
     * 当前源码按 DataResourceRelation 的 `childTable` 匹配子资源 default 视图。
     * 计算列先于 `view.aggregates` 求值，因此视图级聚合可以聚合计算列。
     *
     * @example
     * `"price * qty"`
     * `"firstName + ' ' + lastName"`
     * `"ctx.taxRate ? amount * ctx.taxRate : amount"`
     * `"$sum('OrderItems', 'amount')"`
     * `"$count('OrderItems')"`
     * `"$join('Tags', 'name', ' | ')"`
     */
    computeExpression?: string;
    /**
     * 枚举选项（`type` 为 `enum` 时由标准组件 autoColumns 生成 `r-select`）。
     */
    enumOptions?: ReadonlyArray<Readonly<{
        value: string;
        label: string;
    }>>;
}
 */
数据列定义
分为两个部分：
- **数据属性**（name, type, isPrimaryKey, ...）：描述数据结构，供校验 / 计算列 / CRUD 使用
- **渲染属性**（label, visible, editable, ...）：描述 UI 呈现方式，供表格 / 表单组件消费
渲染属性均为可选，不影响纯数据层使用。
UI 组件通过 `DataSource.columns` 或 `DataView.columns` 读取列元数据。
type DataColumn {
  列名称
  name: string
  列值类型。已知类型见 `ColumnType`；未知业务类型按 unknown 处理。
  常用值：`'string'` | `'number'` | `'boolean'` | `'date'` | `'datetime'`
  type: ColumnType
  列标题（UI 表头 / 表单标签 / 描述列标题）。未设置时 UI 回退到 `name`
  readonly label: string
  是否允许数据库 NULL 值
  readonly allowDBNull: false | true
  默认值
  readonly defaultValue: unknown
  是否为主键字段
  readonly isPrimaryKey: false | true
  是否自增
  readonly autoIncrement: false | true
  正式模型字段是否允许作为通用 AI 批量新增的生成目标列。
  该标志属于 DataTable.columns 字段元数据，不是业务行或 DataView 配置；未设置时按未启用处理。
  此标志不授予数据权限，仍须消费原新增权限与字段权限。
  readonly allowAIAdd: false | true
  是否为框架计算列（如 `_pk`）。
  计算列的值由框架自动维护，不参与序列化（`DataTable.toJson()` 自动排除）。
  UI 组件可通过 `columns.filter(c => !c.isComputed)` 获取用户定义列。
  readonly isComputed: false | true
  UI 必填标记。
  - `true`：表单中必填（生成 required 验证规则）
  - 未设置时回退到 `!allowDBNull`（allowDBNull 显式为 false 也视为必填）
  readonly required: false | true
  字符串最小长度（仅 type 为 string 系列时生效）
  readonly minLength: number
  字符串最大长度（仅 type 为 string 系列时生效）
  readonly maxLength: number
  数值最小值（仅 type 为 number 系列时生效）
  readonly min: number
  数值最大值（仅 type 为 number 系列时生效）
  readonly max: number
  正则校验模式（字符串形式，运行时编译为 RegExp）。
  @example `"^[\\w.-]+@[\\w.-]+\\.\\w+$"`
  readonly pattern: string
  正则校验失败时的自定义提示消息。未设置时使用默认提示
  readonly patternMessage: string
  字符串首尾空白：reject 保存时拒绝，normalize 保存前去除；两者都把纯空白视为空值。
  readonly trim: "reject" | "normalize"
  保存后本视图保留行中的非空值不得重复；只核已加载及待提交行，不替代服务端约束。
  readonly unique: false | true
  仅本视图待新增行可写；既有行字段只读，保存拒绝对其修改。
  readonly immutable: false | true
  保存前核对非空值在选项视图中唯一存在；fill 在本字段新增或变更时把匹配选项写回本行。
  readonly optionsView: DataColumnOptionsView
  值函数字段，保存前按 DataViewFilter 值函数合同校验。
  readonly valueFunction: DataColumnValueFunction
  计算列表达式（JS 表达式字符串）。
  行字段直接引用（无需前缀），外部上下文通过 `ctx` 对象引用，
  子表聚合通过 `$sum` / `$count` / `$avg` / `$min` / `$max` / `$list` / `$join` 函数。
  当前源码按 DataResourceRelation 的 `childTable` 匹配子资源 default 视图。
  计算列先于 `view.aggregates` 求值，因此视图级聚合可以聚合计算列。
  @example `"price * qty"`
  `"firstName + ' ' + lastName"`
  `"ctx.taxRate ? amount * ctx.taxRate : amount"`
  `"$sum('OrderItems', 'amount')"`
  `"$count('OrderItems')"`
  `"$join('Tags', 'name', ' | ')"`
  readonly computeExpression: string
  枚举选项（`type` 为 `enum` 时由标准组件 autoColumns 生成 `r-select`）。
  readonly enumOptions: { value: string; label: string }[]
}

constructorSignature.jsdoc:
创建数据视图实例。
@param tableName 视图所属表名。
@param viewId 视图 ID，默认 `default` 表示主数据视图。

attributes.jsdoc:
当前查询来源接受的字段目录，用于查询配置、参数及函数候选。
绑定适配器可按正式来源收窄；未提供时沿用DataTable普通字段，排除本地计算与框架主键。
与columns的显示投影、fieldAccess的当次数据权限分开；不查询、不缓存、不序列化。
@returns 当前来源可查询字段；可包含本视图未选择输出的正式字段。
@throws 视图销毁、绑定身份或来源作用域失效时拒绝旧目录。

methods.jsdoc:
在同一DataTable创建独立命名查询视图，复用查询owner和查询配置，不复制行、选择、草稿或权限。
辅助查询不继承页面完成函数；确需完成动作的消费者须显式配置onRequestComplete。
@param viewId 新视图身份，须在所属模型内唯一。
@returns 由DataTable持有的视图；使用方释放时调用dataTable.destroyView。
@throws 源已释放、无所属表或视图身份重复时拒绝创建。

预览绑定资源的远端来源，不替换查询结果或未提交修改。
@returns 原文及本地基线版本；不存在的远端以content:null表达。
@throws 无显式来源适配、身份失效或远端读取失败时拒绝。

再核对已预览的来源并接纳；只在存储核验成功后取消明确指定视图的修改。
@param snapshot 已展示的原文及版本，资源适配核对当前存储后才能应用。
@param options 允许放弃的同源视图；其余草稿及在途新修改会阻止采用。
@returns 来源已应用；查询结果由调用流程按需refresh，不隐式加载其他工作区。
@throws 远端变化、读取失败、其他草稿、身份或异步状态改变时保留本地修改并拒绝。

读取尚未加入视图的新行字段访问合同，不读业务值、不创建行、不查询或保存。
仅沿当前正式查询上下文呈现已有新增字段权限；不会授予额外权限。
查询输入变化、结果失效或视图销毁后拒绝旧权限；addRow/save 仍独立执行原守卫。
@param field 正式 DataTable 中待输入的字段名。
@returns 该字段对当前查询新行的只读呈现/写入合同；未知或不可写字段返回拒绝结果。

