    /**
     * append-row/prompt-append 从当前作用域行复制并重命名的字段映射。
     * key 是源字段，value 是新行目标字段。
     * @default {}
     */
    inheritFieldMap?: Record<string, string>;
    /**
     * 新增成功后是否将新行设为目标视图 currentRow。
     * @default false
     */
    setCurrentRowOnSuccess?: boolean;
    /**
     * patch-row/patch-current/patch-selected 的静态更新字段。
     * 用于批量写入固定值，例如 {"status":"approved"}。
     * @default {}
     */
    patch?: Record<string, unknown>;
    /**
     * prompt/patch/set-field 使用的单字段名。
     * field/value 成对出现时，只更新一个字段。
     */
    field?: string;
    /**
     * patch/set-field 使用的单字段值。
     * 与 field 配合使用。
     */
    value?: unknown;
    /**
     * 当前内置动作成功后的链式动作。
     * 例如 append-row 成功后再 patch-current 清空草稿表单。
     */
    then?: ActionDescriptor;
    /**
     * 操作成功后的提示文案。
     * @default ""
     */
    successMessage?: string;
    /**
     * 操作失败后的提示文案。
     * @default ""
     */
    failureMessage?: string;
    /**
     * 数据源为空或目标行不存在时的提示文案。
     * @default ""
     */
    emptyMessage?: string;
    /**
     * 运行时异常时的提示文案。
     * @default ""
     */
    errorMessage?: string;
    /**
     * 表单校验失败时的提示文案。
     * @default ""
     */
    validateMessage?: string;
    /**
     * 操作前确认文案；空字符串表示跳过确认。
     * @default ""
     */
    confirmMessage?: string;
    /**
     * 操作前确认标题。
     * @default ""
     */
    confirmTitle?: string;
    /**
     * 操作前确认类型。
     * 由 UI 消息组件解释，常见值为 warning、info、success、error。
     * @default "warning"
     */
    confirmType?: string;
    /**
     * 静默模式；成功/失败提示不展示。
     * @default false
     */
    silent?: boolean;
    /**
     * 当前行字段值匹配此对象时禁用按钮。
     * 常用于 status 等字段控制操作可用性。
     * @default {}
     */
    disabledWhenRow?: Record<string, unknown>;
    /**
     * 样式模板名。
     * 常见值如 primary、toolbar-danger、icon-add。
     */
    template?: string;
    /**
     * 按钮文本。
     * @default ""
     */
    label?: string;
    /**
     * 按钮类型。
     * 传给底层按钮组件的视觉类型。
     */
    buttonType?: string;
    /**
     * 按钮尺寸。
     * Element Plus 按钮尺寸只允许 default、small、large。
     * @default "default"
     */
    buttonSize?: string;
    /**
     * 是否朴素按钮。
     * @default false
     */
    plain?: boolean;
    /**
     * 是否文本按钮。
     * @default false
     */
    text?: boolean;
    /**
     * 文本按钮是否显示背景。
     * @default false
     */
    bg?: boolean;
    /**
     * 是否链接风格。
     * @default false
     */
    link?: boolean;
    /**
     * 是否圆角。
     * @default false
     */
    round?: boolean;
    /**
     * 是否圆形按钮。
     * @default false
     */
    circle?: boolean;
    /**
     * 是否加载中。
     * @default false
     */
    loading?: boolean;
    /**
     * 图标名称。
     * 使用当前图标注册表中的图标名。
     */
    icon?: string;
    /**
     * 中文按钮文案是否自动插空格。
     * @default false
     */
    autoInsertSpace?: boolean;
    /**
     * 自定义颜色。
     * 传给底层按钮组件的颜色值。
     */
    color?: string;
    /**
     * 是否使用深色主题。
     * @default false
     */
    dark?: boolean;
}

